{
  "root_causes": [
    {
      "service": "ts-travel2-service",
      "fault_kind": "pod_failure",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT 'nor' p, attr_k8s_pod_name pod, min(value) mn, max(value) mx FROM normal_metrics WHERE metric='k8s.container.restarts' AND attr_k8s_pod_name LIKE '%travel2%' GROUP BY ALL UNION ALL SELECT 'abn', attr_k8s_pod_name, min(value), max(value) FROM abnormal_metrics WHERE metric='k8s.container.restarts' AND attr_k8s_pod_name LIKE '%travel2%' GROUP BY ALL",
          "claim": "Travel2 container restart counter rose from 0 in normal period to 1 in the incident, same pod name."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, level, message, attr_k8s_pod_name, time FROM abnormal_logs WHERE level='SEVERE' AND service_name='ts-route-plan-service' AND message LIKE '%Connection refused%' LIMIT 5",
          "claim": "Route-plan logs SEVERE 'Connection refused' on POST to ts-travel2-service trips/routes endpoint."
        },
        {
          "kind": "trace",
          "sql": "SELECT date_trunc('minute', time) m, service_name, count(*) n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name IN ('ts-travel2-service','ts-route-plan-service') AND attr_span_kind='Server' GROUP BY ALL ORDER BY 1,2",
          "claim": "Route-plan server errors cluster at 14:29-14:31 while travel2 served no requests until about 14:30:33 after restart."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-travel2-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, c.span_name, c.attr_status_code, count(*) n, count(p.span_id) with_child FROM abnormal_traces c LEFT JOIN abnormal_traces p ON c.trace_id=p.trace_id AND p.parent_span_id=c.span_id WHERE c.service_name='ts-route-plan-service' AND c.attr_span_kind='Client' GROUP BY ALL",
          "claim": "76 route-plan client POST spans to travel2 are Error with no child span, versus 381 successful POSTs with children."
        }
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_http_response_status_code code, attr_status_code st, count(*) n FROM abnormal_traces WHERE service_name IN ('ts-route-plan-service','ts-travel-plan-service') AND attr_http_response_status_code>=400 GROUP BY ALL ORDER BY n DESC",
          "claim": "Route-plan server 500s are mirrored by travel-plan client POST 500s on the same routePlan endpoints."
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_http_response_status_code code, attr_status_code st, count(*) n FROM abnormal_traces WHERE service_name IN ('ts-travel-plan-service','ts-ui-dashboard') AND attr_status_code='Error' GROUP BY ALL ORDER BY n DESC",
          "claim": "Travel-plan server errors (about 17%) propagate to ts-ui-dashboard, the user-facing entry, which shows the matching error count."
        }
      ]
    }
  ]
}
